function later(value, ms) {
  return new Promise((resolve) => setTimeout(() => resolve(value), ms));
}

later(1, 10)
  .then((n) => {
    later(n + 1, 10).then((m) => console.log("inner " + m));
    return n + 10;
  })
  .then((n) => {
    console.log("outer " + n);
    return later(n * 2, 35);
  })
  .then((n) => console.log("last " + n));
